  // How a quick answer reads, for colours and statistics: good | partial | concern | unknown | fact | na
  function answerSignal(q, a) {
    if (!a) return null;
    if (a === 'N/A') return 'na';
    if (a === "Don't know") return 'unknown';
    if (q.type === 'open') return a === 'Clear' ? 'good' : 'partial';
    if (a === 'Partly') return 'partial';
    if (q.concern === 'none') return 'fact';
    const concernAnswer = q.concern === 'yes' ? 'Yes' : 'No';
    return a === concernAnswer ? 'concern' : 'good';
  }

